pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {demo} from "../src/demo.sol";

contract InvMutTest is Test {
    demo c;
    function setUp() public { c = new demo(); }
    function testRegression_property() public {
        TokenMock dummyToken = new TokenMock();
        address alice = address(0x1111);
        address bob = address(0x2222);
        address[] memory tos = new address[](1);
        tos[0] = bob;

        bool success;
        try c.transfer(alice, address(dummyToken), tos, 100) {
            success = true;
        } catch {
            success = false;
        }

        assertTrue(success == true);
    }
}

contract TokenMock {
    fallback(bytes calldata) external returns (bytes memory) {
        if (msg.sig == bytes4(keccak256("transferFrom(address,address,uint256)"))) {
            return "";
        }
        revert("unexpected call");
    }
}
